INSERT INTO `contacts` (`id`, `name`, `email`, `mobile_number`, `subject`, `message`, `seen`, `feedback`, `created_at`, `updated_at`, `reply`) VALUES
(1, 'Rushab Shirke', 'thedigiemperor@gmail.com', '+97109137553923', 'sfsffs', 'test', 0, '0', '2025-09-18 18:00:11', '2025-09-18 18:00:11', NULL),
(2, 'saurabh', 'sawant@gmail.com', '+97109137553923', 'test', 'test', 0, '0', '2025-09-18 18:03:23', '2025-09-18 18:03:23', NULL),
(3, 'Martin', 'xinfa957@gmail.com', '+8615203373515', 'cable supply', 'I am Martin, Sales Manager from Xinfa Wire & Cable Company of China. We are a source factory of electric power cables and can supply various types of cables with good quality and competitive prices, such as low & medium voltage power cables, control cables, and overhead cables.', 1, '0', '2025-11-19 10:04:17', '2025-12-15 18:57:00', NULL),
(4, 'Sarah H', 'manager@sarahhowell.org', '+13435603935', 'Inquiry', 'Subject: Inquiry About Your Products & Request for Catalog\r\n\r\nDear Sir / Ma \r\n\r\nI hope this email finds you well.\r\n\r\nI am reaching out to express my interest in your products and explore potential business opportunities with your company. I would appreciate it if you could provide me with your latest product catalog, including pricing, specifications, and any available terms for bulk or wholesale purchases.\r\n\r\nAdditionally, if you have any recommendations or best-selling items, I would love to learn more about them. Please let me know if there are any specific requirements or processes to proceed further.\r\n\r\nLooking forward to your response and the possibility of working together.\r\n\r\n\r\nSARAH GROUPS LTD \r\n\r\nContact:\r\nEmail:manager@sarahhowell.org\r\nWhatsapp:+13435603935\r\n\r\nBest regards,\r\nSarah Howell \r\nmanager', 1, '0', '2025-12-08 13:40:12', '2025-12-15 18:53:05', NULL),
(5, 'Al-Fateh Customs Clearance and Logistics Company', 'marketing@alfatehlogistics.com', '+9710800200300', 'Customs Clearance Services for Smart Sense Supplies', 'Hi Sir,\r\n\r\nWe would like to offer you our professional customs clearance services for your import and export operations.\r\n\r\nCould you kindly provide the contact details of your Import/Export, or connect us with them directly, so we may arrange a meeting to better understand your requirements\r\n\r\nAl-Fateh Customs Clearance and Logistics Company is fully prepared to support you with all customs procedures related to imports and exports—promptly, efficiently, and reliably.\r\n\r\nFor further information, please contact us at 800 200 300.\r\n\r\nThank you, and we look forward to serving you.\r\n\r\nAl-Fateh Customs Clearance and Logistics Company', 0, '0', '2025-12-27 18:22:02', '2025-12-27 18:22:02', NULL);
