INSERT INTO `email_templates` (`id`, `template_name`, `user_type`, `template_design_name`, `title`, `body`, `banner_image`, `image`, `logo`, `button_name`, `button_url`, `footer_text`, `copyright_text`, `pages`, `social_media`, `hide_field`, `button_content_status`, `product_information_status`, `order_information_status`, `status`, `created_at`, `updated_at`) VALUES
(1, 'order-received', 'admin', 'order-received', 'New Order Received', '<p><b>Hi {adminName},</b></p><p>We have sent you this email to notify that you have a new order.You will be able to see your orders after login to your panel.</p>', NULL, NULL, NULL, NULL, NULL, 'Please contact us for any queries, we are always happy to help.', 'Copyright 2025 . All right reserved.', NULL, NULL, '[\"icon\",\"product_information\",\"button_content\",\"banner_image\"]', 1, 1, 1, 1, '2025-04-21 17:05:10', '2025-04-21 17:05:10'),
(2, 'order-place', 'customer', 'order-place', 'Order # {orderId} Has Been Placed Successfully!', '<p><b>Hi {userName},</b></p><p>Your order from {shopName} has been placed to know the current status of your order click track order</p>', NULL, NULL, NULL, NULL, NULL, 'Please contact us for any queries,New-messages._we_are_always_happy_to_help.', 'Copyright 2025 . All right reserved.', NULL, NULL, '[\"icon\",\"product_information\",\"banner_image\"]', 1, 1, 1, 1, '2025-04-21 17:05:10', '2025-04-21 17:05:10'),
(3, 'registration-verification', 'customer', 'registration-verification', 'Registration Verification', '<p><b>Hi {userName},</b></p><p>Your verification code is</p>', NULL, NULL, NULL, NULL, NULL, 'Please contact us for any queries,New-messages._we_are_always_happy_to_help.', 'Copyright 2025 . All right reserved.', NULL, NULL, '[\"product_information\",\"order_information\",\"button_content\",\"banner_image\"]', 1, 1, 1, 1, '2025-04-21 17:05:10', '2025-04-21 17:05:10'),
(4, 'registration-from-pos', 'customer', 'registration-from-pos', 'Registration Complete', '<p><b>Hi {userName},</b></p><p>Thank you for joining  Shop.If you want to become a registered customer then reset your password below by using this email. Then you’ll be able to explore the website and app as a registered customer.</p>', NULL, NULL, NULL, NULL, NULL, 'Please contact us for any queries,New-messages._we_are_always_happy_to_help.', 'Copyright 2025 . All right reserved.', NULL, NULL, '[\"product_information\",\"order_information\",\"button_url\",\"button_content_status\",\"banner_image\"]', 1, 1, 1, 1, '2025-04-21 17:05:10', '2025-04-21 17:05:10'),
(5, 'account-block', 'customer', 'account-block', 'Account Blocked', '<div><b>Hi {userName},</b></div><div><b><br></b></div><div>Your account has been blocked due to suspicious activity by the admin .To resolve this issue please contact with admin or support center. We apologize for any inconvenience caused.</div><div><br></div><div>Meanwhile, click here to visit theshop website</div><div><font color=\"#0000ff\"> <a href=\"http://127.0.0.1:8000\" target=\"_blank\">http://127.0.0.1:8000</a></font></div>', NULL, NULL, NULL, NULL, NULL, 'Please contact us for any queries,New-messages._we_are_always_happy_to_help.', 'Copyright 2025 . All right reserved.', NULL, NULL, '[\"product_information\",\"order_information\",\"button_content\",\"banner_image\"]', 1, 1, 1, 1, '2025-04-21 17:05:11', '2025-04-21 17:05:11'),
(6, 'account-unblock', 'customer', 'account-unblock', 'Account Unblocked', '<div><b>Hi {userName},</b></div><div><b><br></b></div><div>Your account has been successfully unblocked. We appreciate your cooperation in resolving this issue. Thank you for your understanding and patience. </div><div><br></div><div>Meanwhile, click here to visit the shop website</div><div><font color=\"#0000ff\"> <a href=\"http://127.0.0.1:8000\" target=\"_blank\">http://127.0.0.1:8000</a></font></div>', NULL, NULL, NULL, NULL, NULL, 'Please contact us for any queries,New-messages._we_are_always_happy_to_help.', 'Copyright 2025 . All right reserved.', NULL, NULL, '[\"product_information\",\"order_information\",\"button_content\",\"banner_image\"]', 1, 1, 1, 1, '2025-04-21 17:05:11', '2025-04-21 17:05:11'),
(7, 'digital-product-download', 'customer', 'digital-product-download', 'Congratulations', '<p>Thank you for choosing  shop! Your digital product is ready for download. To download your product use your email <b>{emailId}</b> and order # {orderId} below.</b><br></p>', NULL, NULL, NULL, NULL, NULL, 'Please contact us for any queries,New-messages._we_are_always_happy_to_help.', 'Copyright 2025 . All right reserved.', NULL, NULL, '[\"product_information\",\"button_content\",\"banner_image\"]', 1, 1, 1, 1, '2025-04-21 17:05:11', '2025-04-21 17:05:11'),
(8, 'digital-product-otp', 'customer', 'digital-product-otp', 'Digital Product Download OTP Verification', '<p><b>Hi {userName},</b></p><p>Your verification code is</p>', NULL, NULL, NULL, NULL, NULL, 'Please contact us for any queries,New-messages._we_are_always_happy_to_help.', 'Copyright 2025 . All right reserved.', NULL, NULL, '[\"product_information\",\"order_information\",\"button_content\",\"banner_image\"]', 1, 1, 1, 1, '2025-04-21 17:05:11', '2025-04-21 17:05:11'),
(9, 'add-fund-to-wallet', 'customer', 'add-fund-to-wallet', 'Transaction Successful', '<div style=\"text-align: center; \">Amount successfully credited to your wallet .</div><div style=\"text-align: center; \"><br></div>', NULL, NULL, NULL, NULL, NULL, 'Please contact us for any queries,New-messages._we_are_always_happy_to_help.', 'Copyright 2025 . All right reserved.', NULL, NULL, '[\"product_information\",\"order_information\",\"button_content\",\"banner_image\"]', 1, 1, 1, 1, '2025-04-21 17:05:11', '2025-04-21 17:05:11'),
(10, 'registration', 'vendor', 'registration', 'Registration Complete', '<div><b>Hi {vendorName},</b></div><div><b><br></b></div><div>Congratulation! Your registration request has been send to admin successfully! Please wait until admin reviewal. </div><div><br></div><div>meanwhile click here to visit the  Shop Website</div><div><font color=\"#0000ff\"> <a href=\"http://127.0.0.1:8000\" target=\"_blank\">http://127.0.0.1:8000</a></font></div>', NULL, NULL, NULL, NULL, NULL, 'Please contact us for any queries,New-messages._we_are_always_happy_to_help.', 'Copyright 2025 . All right reserved.', NULL, NULL, '[\"product_information\",\"order_information\",\"button_content\",\"banner_image\"]', 1, 1, 1, 1, '2025-04-21 17:05:11', '2025-04-21 17:05:11'),
(11, 'registration-approved', 'vendor', 'registration-approved', 'Registration Approved', '<div><b>Hi {vendorName},</b></div><div><b><br></b></div><div>Your registration request has been approved by admin. Now you can complete your store setting and start selling your product on  Shop. </div><div><br></div><div>Meanwhile, click here to visit the shop website</div><div><font color=\"#0000ff\"> <a href=\"http://127.0.0.1:8000\" target=\"_blank\">http://127.0.0.1:8000</a></font></div>', NULL, NULL, NULL, NULL, NULL, 'Please contact us for any queries,New-messages._we_are_always_happy_to_help.', 'Copyright 2025 . All right reserved.', NULL, NULL, '[\"product_information\",\"order_information\",\"button_content\",\"banner_image\"]', 1, 1, 1, 1, '2025-04-21 17:05:11', '2025-04-21 17:05:11'),
(12, 'registration-denied', 'vendor', 'registration-denied', 'Registration Denied', '<div><b>Hi {vendorName},</b></div><div><b><br></b></div><div>Your registration request has been denied by admin. Please contact with admin or support center if you have any queries.</div><div><br></div><div>Meanwhile, click here to visit the shop website</div><div><font color=\"#0000ff\"> <a href=\"http://127.0.0.1:8000\" target=\"_blank\">http://127.0.0.1:8000</a></font></div>', NULL, NULL, NULL, NULL, NULL, 'Please contact us for any queries,New-messages._we_are_always_happy_to_help.', 'Copyright 2025 . All right reserved.', NULL, NULL, '[\"product_information\",\"order_information\",\"button_content\",\"banner_image\"]', 1, 1, 1, 1, '2025-04-21 17:05:11', '2025-04-21 17:05:11'),
(13, 'account-suspended', 'vendor', 'account-suspended', 'Account Suspended', '<div><b>Hi {vendorName},</b></div><div><b><br></b></div><div>Your account access has been suspended by admin.From now you can access your app and panel again Please contact us for any queries we’re always happy to help.</div><div><br></div><div>Meanwhile, click here to visit the shop website</div><div><font color=\"#0000ff\"> <a href=\"http://127.0.0.1:8000\" target=\"_blank\">http://127.0.0.1:8000</a></font></div>', NULL, NULL, NULL, NULL, NULL, 'Please contact us for any queries,New-messages._we_are_always_happy_to_help.', 'Copyright 2025 . All right reserved.', NULL, NULL, '[\"product_information\",\"order_information\",\"button_content\",\"banner_image\"]', 1, 1, 1, 1, '2025-04-21 17:05:11', '2025-04-21 17:05:11'),
(14, 'account-activation', 'vendor', 'account-activation', 'Account Activation', '<div><b>Hi {vendorName},</b></div><div><b><br></b></div><div>Your account suspension has been revoked by admin. From now you can access your app and panel again Please contact us for any queries we’re always happy to help.</div><div><br></div><div>Meanwhile, click here to visit the shop website</div><div><font color=\"#0000ff\"> <a href=\"http://127.0.0.1:8000\" target=\"_blank\">http://127.0.0.1:8000</a></font></div>', NULL, NULL, NULL, NULL, NULL, 'Please contact us for any queries,New-messages._we_are_always_happy_to_help.', 'Copyright 2025 . All right reserved.', NULL, NULL, '[\"product_information\",\"order_information\",\"button_content\",\"banner_image\"]', 1, 1, 1, 1, '2025-04-21 17:05:11', '2025-04-21 17:05:11'),
(15, 'forgot-password', 'vendor', 'forgot-password', 'Change Password Request', '<p><b>Hi {vendorName},</b></p><p>Please click the link below to change your password.</p>', NULL, NULL, NULL, NULL, NULL, 'Please contact us for any queries,New-messages._we_are_always_happy_to_help.', 'Copyright 2025 . All right reserved.', NULL, NULL, '[\"product_information\",\"order_information\",\"button_content\",\"banner_image\"]', 1, 1, 1, 1, '2025-04-21 17:05:11', '2025-04-21 17:05:11'),
(16, 'order-received', 'vendor', 'order-received', 'New Order Received', '<p><b>Hi {vendorName},</b></p><p>We have sent you this email to notify that you have a new order.You will be able to see your orders after login to your panel.</p>', NULL, NULL, NULL, NULL, NULL, 'Please contact us for any queries,New-messages._we_are_always_happy_to_help.', 'Copyright 2025 . All right reserved.', NULL, NULL, '[\"icon\",\"product_information\",\"button_content\",\"banner_image\"]', 1, 1, 1, 1, '2025-04-21 17:05:11', '2025-04-21 17:05:11'),
(17, 'reset-password-verification', 'delivery-man', 'reset-password-verification', 'OTP Verification For Password Reset', '<p><b>Hi {deliveryManName},</b></p><p>Your verification code is</p>', NULL, NULL, NULL, NULL, NULL, 'Please contact us for any queries,New-messages._we_are_always_happy_to_help.', 'Copyright 2025 . All right reserved.', NULL, NULL, '[\"product_information\",\"order_information\",\"button_content\",\"banner_image\"]', 1, 1, 1, 1, '2025-04-21 17:05:11', '2025-04-21 17:05:11');
