(231, 246, 'Single core wire', 'Single core wire', '', '', '', '', '0', '0', '-1', '0', '-1', '0', 'large', '2025-09-20-68ce4c9cc4dee.webp', '2025-09-20 13:41:32', '2025-09-20 13:41:32'),
(232, 247, 'Ceramic Lamp Holder', 'It uses the highest quality brass as the material and has good anti-rust properties, Retro design will being you a stylish look, EU plug to E27 LED light bulb adapter converter', '', '', '', '', '0', '0', '-1', '0', '-1', '0', 'large', '2025-09-20-68ce91eb8e100.webp', '2025-09-20 18:37:15', '2025-09-26 13:15:19'),
(233, 248, 'Professional Optical Level', 'Professional Optical Level is Construction engineering survey, deformationd subsidence monitoring, mining survey, etc.dustproof  and waterproof', '', '', '', '', '0', '0', '-1', '0', '-1', '0', 'large', '2025-09-20-68ce92fc31009.webp', '2025-09-20 18:41:48', '2025-09-26 13:13:22'),
