(235, 250, 'Table Connectivity Box', 'Plug this popup box and play with HydraulicButton activated soft openingAvailable configuration - HDMI, VGA, USB, AudioProvides a non-stop connectivity solution', '', '', '', '', '0', '0', '-1', '0', '-1', '0', 'large', '2025-09-20-68ce9480f2f4a.webp', '2025-09-20 18:48:17', '2025-09-26 12:20:55'),
(236, 251, 'Signal Lights', 'Discover high-quality Signal Lights at Smart Sense Supplies – designed for safety, visibility, and durability. Ideal for industrial, commercial, and traffic applications across Dubai & UAE.', '', '', '', '', '0', '0', '-1', '0', '-1', '0', 'large', '2025-09-20-68ce94f671729.webp', '2025-09-20 18:50:14', '2025-09-23 18:51:42'),
